using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Web.Script.Serialization;

// Real Windows temporary-file I/O. VM state, protection and space admission
// are adapters, not real Hyper-V, protected ACL or disk-full acceptance.
public static class MuOfflineSnapshotFixture {
    public sealed class ProcessState {public string id,snapshotId,boundary,previousDisk,previousSeed,snapshotDisk,snapshotSeed;}
    public static string RunProcess(string root,string mode,string boundary){
        string stateFile=Path.Combine(root,"state.json");var serializer=new JavaScriptSerializer();ProcessState state;
        Action<string> dir=p=>{string full=Path.GetFullPath(p);if(!full.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Process fixture boundary changed");Directory.CreateDirectory(full);};
        Func<string,FileStream> read=p=>{string full=Path.GetFullPath(p);if(!full.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Process fixture boundary changed");if((File.GetAttributes(full)&FileAttributes.ReparsePoint)!=0)throw new UnauthorizedAccessException("Process fixture reparse rejected");return new FileStream(full,FileMode.Open,FileAccess.Read,FileShare.Read);};
        if(mode=="prepare"){
            if(File.Exists(stateFile))throw new InvalidOperationException("Fixture initial state already exists");state=new ProcessState{id=Guid.NewGuid().ToString("D"),boundary=boundary};string allocation=Path.Combine(root,state.id);dir(allocation);
            string disk=Path.Combine(allocation,"disk.vhdx"),seed=Path.Combine(allocation,"seed.iso");File.WriteAllBytes(disk,Bytes(3*1048576,91));File.WriteAllBytes(seed,Bytes(65536,92));state.snapshotDisk=Hash(disk);state.snapshotSeed=Hash(seed);
            var store=new MuOfflineSnapshotStore(allocation,state.id,dir,read,bytes=>{},()=>{},point=>{
                if(point!=boundary)return;
                var receipt=new {pid=System.Diagnostics.Process.GetCurrentProcess().Id,id=state.id,snapshotId=state.snapshotId,boundary=point,operation="snapshot-restore-paused",time=DateTime.UtcNow.ToString("o")};
                byte[] data=Encoding.UTF8.GetBytes(serializer.Serialize(receipt));string next=Path.Combine(root,"ready.next");using(var output=new FileStream(next,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(data,0,data.Length);output.Flush(true);}File.Move(next,Path.Combine(root,"ready.json"));
                using(var never=new ManualResetEvent(false)){never.WaitOne(60000);}throw new TimeoutException("Fixture was not terminated at its bound restore boundary");
            });
            state.snapshotId=store.Create("进程恢复","owner-encrypted-snapshot-configuration",CancellationToken.None).id;
            File.WriteAllBytes(disk,Bytes(3*1048576,93));File.WriteAllBytes(seed,Bytes(65536,94));state.previousDisk=Hash(disk);state.previousSeed=Hash(seed);
            using(var output=new FileStream(stateFile,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=Encoding.UTF8.GetBytes(serializer.Serialize(state));output.Write(data,0,data.Length);output.Flush(true);}
            var applied=store.PrepareRestore(state.snapshotId,"owner-encrypted-current-configuration",CancellationToken.None);store.CommitRestore(applied.id);throw new InvalidOperationException("Fixture boundary not reached");
        }
        if(mode!="recover")throw new ArgumentException("Unknown fixture mode");
        state=serializer.Deserialize<ProcessState>(File.ReadAllText(stateFile));Guid parsed;if(!Guid.TryParseExact(state.id,"D",out parsed)||parsed.ToString("D")!=state.id)throw new InvalidDataException("Process fixture state identity changed");
        string target=Path.Combine(root,state.id);var resumed=new MuOfflineSnapshotStore(target,state.id,dir,read,bytes=>{},()=>{},point=>{}).RecoverRestore();bool committed=state.boundary=="restore-committed";
        Require(resumed!=null&&resumed.snapshotId==state.snapshotId&&resumed.phase==(committed?"committed":"rolled-back"),"New process did not recover bound transaction");
        Require(Hash(Path.Combine(target,"disk.vhdx"))==(committed?state.snapshotDisk:state.previousDisk)&&Hash(Path.Combine(target,"seed.iso"))==(committed?state.snapshotSeed:state.previousSeed),"New process did not preserve paired disk and seed version");
        Require((committed?resumed.configuration:resumed.previousConfiguration)==(committed?"owner-encrypted-snapshot-configuration":"owner-encrypted-current-configuration"),"New process recovered wrong configuration");
        return serializer.Serialize(new {complete=true,pid=System.Diagnostics.Process.GetCurrentProcess().Id,id=state.id,snapshotId=state.snapshotId,boundary=state.boundary,phase=resumed.phase,pairedDiskSeedAndConfigurationSelectionVerified=true,configurationPersistenceExercised=false,oldTransactionAndFilesRetained=Directory.Exists(Path.Combine(target,"snapshots","restore-active")),realHyperVExercised=false,protectedAclExercised=false,realDiskFullExercised=false,productSnapshotFeatureEnabled=false});
    }
    private static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
    private static string Hash(string file){using(var input=File.OpenRead(file))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(input));}
    private static byte[] Bytes(int size,byte value){var bytes=new byte[size];for(int i=0;i<size;i++)bytes[i]=value;return bytes;}
    private static bool Fails(Action action){try{action();return false;}catch(IOException){return true;}catch(InvalidDataException){return true;}catch(InvalidOperationException){return true;}catch(OperationCanceledException){return true;}catch(UnauthorizedAccessException){return true;}}
    private sealed class Case {
        public string root,allocation,id,disk,seed,initialDisk,initialSeed,currentDisk,currentSeed;
        public Action<string> step;
        public Action<long> reservation;
        public bool running;
        public long reserved;
        public Case(string parent,string name){
            root=Path.Combine(parent,name);Directory.CreateDirectory(root);id=Guid.NewGuid().ToString("D");allocation=Path.Combine(root,id);Directory.CreateDirectory(allocation);
            disk=Path.Combine(allocation,"disk.vhdx");seed=Path.Combine(allocation,"seed.iso");File.WriteAllBytes(disk,Bytes(3*1048576,31));File.WriteAllBytes(seed,Bytes(65536,41));initialDisk=Hash(disk);initialSeed=Hash(seed);
        }
        private void Boundary(string path){string full=Path.GetFullPath(path);if(!full.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Fixture path outside temporary case");string next=full;while(next.Length>root.Length){if(File.Exists(next)||Directory.Exists(next))if((File.GetAttributes(next)&FileAttributes.ReparsePoint)!=0)throw new UnauthorizedAccessException("Fixture reparse rejected");next=Path.GetDirectoryName(next);}}
        public MuOfflineSnapshotStore Store(){return new MuOfflineSnapshotStore(allocation,id,p=>{Boundary(p);Directory.CreateDirectory(p);},p=>{Boundary(p);return new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read);},bytes=>{reserved=bytes;if(reservation!=null)reservation(bytes);},()=>{if(running)throw new InvalidOperationException("Fixture VM is running");},p=>{if(step!=null)step(p);});}
        public MuOfflineSnapshotStore.Snapshot Snapshot(){return Store().Create("中文快照","owner-encrypted-snapshot-configuration",CancellationToken.None);}
        public void ChangeCurrent(){File.WriteAllBytes(disk,Bytes(3*1048576,51));File.WriteAllBytes(seed,Bytes(65536,61));currentDisk=Hash(disk);currentSeed=Hash(seed);}
        public void Original(){Require(Hash(disk)==initialDisk&&Hash(seed)==initialSeed,"Snapshot version did not match");}
        public void Current(){Require(Hash(disk)==currentDisk&&Hash(seed)==currentSeed,"Current disk or seed changed unexpectedly");}
        public string Active {get{return Path.Combine(allocation,"snapshots","restore-active");}}
        public void Interrupt(string point,Action action){bool triggered=false;step=p=>{if(p==point){triggered=true;throw new IOException("Synthetic interruption "+p);}};Require(Fails(action),"Interruption was not surfaced");step=null;Require(triggered,"Requested boundary was not reached");}
        public void Recovered(string phase){var recovered=Store().RecoverRestore();Require(recovered!=null&&recovered.phase==phase,"Recovery phase changed");Require((phase=="committed"?recovered.configuration:recovered.previousConfiguration)==(phase=="committed"?"owner-encrypted-snapshot-configuration":"owner-encrypted-current-configuration"),"Recovery configuration was not paired with disk version");}
    }
    public static string Run(string parent){
        var results=new List<object>();
        Action<string,Action<Case>> test=(name,run)=>{var c=new Case(parent,name);try{run(c);}catch(Exception error){throw new Exception("Snapshot case "+name+": "+error.Message,error);}results.Add(new {name=name,passed=true});};
        test("stale-recovery-cannot-select-another-transaction",c=>{
            var snapshot=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(snapshot.id,"owner-encrypted-current-configuration",CancellationToken.None);c.Original();Require(Fails(()=>c.Store().RecoverRestore(Guid.NewGuid().ToString("D"))),"Unrelated recovery changed the active transaction");c.Original();Require(c.Store().Pending().phase=="applied","Unrelated recovery changed its decision");Require(c.Store().RecoverRestore(applied.id).phase=="rolled-back","Exact recovery was not resumed");c.Current();
        });
        test("acknowledged-history-proves-exact-decision-without-current-disk-replay",c=>{
            var snapshot=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(snapshot.id,"owner-encrypted-current-configuration",CancellationToken.None);c.Store().CommitRestore(applied.id);c.Store().AcknowledgeRestore(applied.id);
            File.WriteAllBytes(c.disk,Bytes(3*1048576,87));File.WriteAllBytes(c.seed,Bytes(65536,88));string laterDisk=Hash(c.disk),laterSeed=Hash(c.seed);
            var history=c.Store().History(applied.id);Require(history.id==applied.id&&history.snapshotId==snapshot.id&&history.phase=="committed"&&history.configuration=="owner-encrypted-snapshot-configuration","Acknowledged decision was lost");Require(c.Store().Pending()==null&&Hash(c.disk)==laterDisk&&Hash(c.seed)==laterSeed,"History lookup replayed later files");Require(Fails(()=>c.Store().History(Guid.NewGuid().ToString("D"))),"Unknown acknowledged transaction accepted");
        });
        test("coordinator-published-with-restore-and-rebound-before-recovery",c=>{
            var snapshot=c.Snapshot();c.ChangeCurrent();string actor="owner-process-one",replacement="owner-process-two";
            c.Interrupt("restore-replaced-disk",()=>c.Store().PrepareRestore(snapshot.id,"owner-encrypted-current-configuration",CancellationToken.None,actor));
            var pending=c.Store().Pending();Require(pending.coordinator==actor,"Controller was not durably published with the initial transaction");
            Require(Fails(()=>c.Store().BindCoordinator(Guid.NewGuid().ToString("D"),actor,replacement)),"Foreign transaction adopted");Require(Fails(()=>c.Store().BindCoordinator(pending.id,"stale-controller",replacement)),"Changed coordinator adopted");
            c.Interrupt("restore-coordinator-bound",()=>c.Store().BindCoordinator(pending.id,actor,replacement));
            var bound=c.Store().Pending();Require(bound.coordinator==replacement&&bound.phase==pending.phase&&bound.id==pending.id,"Coordinator adoption was not atomic or changed the decision");
            var recovered=c.Store().RecoverRestore();Require(recovered.coordinator==replacement&&recovered.phase=="rolled-back","Recovery lost adopted controller");c.Current();
        });
        test("legacy-coordinator-and-strict-journal-extension",c=>{
            var snapshot=c.Snapshot();c.ChangeCurrent();var pending=c.Store().PrepareRestore(snapshot.id,"owner-encrypted-current-configuration",CancellationToken.None);
            string journal=Path.Combine(c.Active,"journal.json"),original=File.ReadAllText(journal);var json=new JavaScriptSerializer();var raw=json.Deserialize<Dictionary<string,object>>(original);raw.Remove("coordinator");File.WriteAllText(journal,json.Serialize(raw));
            Require(c.Store().Pending().coordinator==null,"Original journal compatibility lost");c.Store().BindCoordinator(pending.id,null,"adopted-controller");Require(c.Store().Pending().coordinator=="adopted-controller","Legacy journal not atomically adopted");
            string adopted=File.ReadAllText(journal);raw=json.Deserialize<Dictionary<string,object>>(adopted);raw["coordinator"]=12;File.WriteAllText(journal,json.Serialize(raw));Require(Fails(()=>c.Store().Pending()),"Non-string coordinator accepted");
            raw["coordinator"]=new string('x',4097);File.WriteAllText(journal,json.Serialize(raw));Require(Fails(()=>c.Store().Pending()),"Unbounded coordinator accepted");
            raw=json.Deserialize<Dictionary<string,object>>(adopted);raw["unknown"]=true;File.WriteAllText(journal,json.Serialize(raw));Require(Fails(()=>c.Store().Pending()),"Unknown journal extension accepted");File.WriteAllText(journal,adopted);c.Recovered("rolled-back");c.Current();
        });
        test("origin-plan-is-bounded-final-and-exactly-retryable",c=>{
            var snapshot=c.Snapshot();c.ChangeCurrent();var pending=c.Store().PrepareRestore(snapshot.id,"owner-encrypted-current-configuration",CancellationToken.None,"controller","broker-origin");
            Require(c.Store().Pending().origin=="broker-origin","Origin binding was not durable before replacement");Require(Fails(()=>c.Store().BindRestoreOrigin(pending.id,"broker-origin","planned-origin")),"Applied decision accepted origin plan");c.Store().CommitRestore(pending.id);
            Require(Fails(()=>c.Store().BindRestoreOrigin(Guid.NewGuid().ToString("D"),"broker-origin","planned-origin")),"Other transaction accepted origin plan");Require(Fails(()=>c.Store().BindRestoreOrigin(pending.id,"stale-origin","planned-origin")),"Stale origin accepted");Require(Fails(()=>c.Store().BindRestoreOrigin(pending.id,"broker-origin",null)),"Missing origin plan accepted");Require(Fails(()=>c.Store().BindRestoreOrigin(pending.id,"broker-origin",new string('x',65537))),"Unbounded origin accepted");
            c.Interrupt("restore-origin-planned",()=>c.Store().BindRestoreOrigin(pending.id,"broker-origin","planned-origin"));Require(c.Store().Pending().origin=="planned-origin","Origin plan was not durable before interruption");Require(Fails(()=>c.Store().BindRestoreOrigin(pending.id,"broker-origin","changed-origin")),"Old plan overwrote committed plan");c.Store().BindRestoreOrigin(pending.id,"planned-origin","planned-origin");
            string path=Path.Combine(c.Active,"journal.json"),original=File.ReadAllText(path);var json=new JavaScriptSerializer();var raw=json.Deserialize<Dictionary<string,object>>(original);raw["origin"]=12;File.WriteAllText(path,json.Serialize(raw));Require(Fails(()=>c.Store().Pending()),"Nonstring origin binding accepted");File.WriteAllText(path,original);c.Store().AcknowledgeRestore(pending.id);c.Original();
        });
        test("complete-copy-and-exclusive-read",c=>{
            bool held=false;c.step=p=>{if(p=="copy-disk"&&!held){held=true;Require(Fails(()=>{using(var stream=new FileStream(c.disk,FileMode.Open,FileAccess.Write,FileShare.ReadWrite)){};}),"Source allowed writes while being captured");}};
            var s=c.Snapshot();c.step=null;c.Original();var listed=c.Store().List();Require(held&&listed.Length==1&&listed[0].id==s.id&&listed[0].environmentId==c.id,"Snapshot was not atomically listed");Require(s.files.Sum(f=>f.bytes)==3*1048576+65536,"Snapshot byte inventory changed");Require(c.reserved>=s.files.Sum(f=>f.bytes),"Snapshot space was not admitted");
        });
        test("create-cancel-not-published",c=>{var cancel=new CancellationTokenSource();c.step=p=>{if(p=="copy-disk")cancel.Cancel();};Require(Fails(()=>c.Store().Create("取消","owner-encrypted",cancel.Token)),"Create cancellation ignored");c.step=null;c.Original();Require(c.Store().List().Length==0,"Cancelled capture was published");});
        test("source-sharing-lock-denied",c=>{using(var held=new FileStream(c.disk,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){Require(Fails(()=>c.Snapshot()),"Capture bypassed independent sharing lock");}c.Original();Require(c.Store().List().Length==0,"Locked source was published");});
        test("space-admission-before-copy",c=>{c.reservation=bytes=>{throw new IOException("Synthetic reservation denied");};Require(Fails(()=>c.Snapshot()),"Space admission ignored");Require(!Directory.EnumerateDirectories(Path.Combine(c.allocation,"snapshots")).Any(),"Staging was created before space admission");c.Original();});
        test("running-denied",c=>{c.running=true;Require(Fails(()=>c.Snapshot()),"Running fixture admitted");c.running=false;c.Original();Require(c.Store().List().Length==0,"Running capture published");});
        test("corrupt-snapshot-before-replace",c=>{var s=c.Snapshot();c.ChangeCurrent();File.WriteAllBytes(Path.Combine(c.allocation,"snapshots",s.id,"disk.vhdx"),Bytes(3*1048576,7));Require(Fails(()=>c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None)),"Corrupt snapshot admitted");c.Current();Require(!Directory.Exists(c.Active),"Corrupt restore published active journal");});
        test("source-changed-before-restore-publish",c=>{var s=c.Snapshot();c.ChangeCurrent();c.step=p=>{if(p=="restore-before-publish")File.WriteAllBytes(c.seed,Bytes(65536,71));};Require(Fails(()=>c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None)),"Concurrent source mutation overwritten");c.step=null;Require(Hash(c.disk)==c.currentDisk&&Hash(c.seed)!=c.currentSeed,"Concurrent source mutation was not preserved");Require(!Directory.Exists(c.Active),"Changed source published active restore");});
        test("commit-and-retained-rollback",c=>{var s=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);Require(applied.phase=="applied"&&applied.configuration==s.configuration,"Applied config missing");c.Original();c.Store().CommitRestore(applied.id);c.Recovered("committed");c.Store().AcknowledgeRestore(applied.id);Require(!Directory.Exists(c.Active),"Acknowledged transaction remained active");var history=Directory.GetDirectories(Path.Combine(c.allocation,"snapshots","restore-history")).Single();Require(Hash(Path.Combine(history,"disk.rollback"))==c.currentDisk&&Hash(Path.Combine(history,"seed.rollback"))==c.currentSeed,"Original rollback was discarded");c.Original();});
        foreach(string boundary in new[]{"restore-prepared","restore-replaced-disk","restore-replaced-seed","restore-applied"}){
            string point=boundary;test("recover-"+point,c=>{var s=c.Snapshot();c.ChangeCurrent();c.Interrupt(point,()=>c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None));c.Recovered("rolled-back");c.Current();c.Recovered("rolled-back");c.Store().AcknowledgeRestore(c.Store().RecoverRestore().id);Require(!Directory.Exists(c.Active),"Rollback acknowledgement failed");});
        }
        test("recover-interrupted-rollback",c=>{var s=c.Snapshot();c.ChangeCurrent();c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);c.Interrupt("recovery-replaced-disk",()=>c.Store().RecoverRestore());c.Recovered("rolled-back");c.Current();});
        test("lost-commit-reply-keeps-new-version",c=>{var s=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);c.Interrupt("restore-committed",()=>c.Store().CommitRestore(applied.id));c.Recovered("committed");c.Original();});
        test("corrupt-rollback-preflight-preserves-all-targets",c=>{var s=c.Snapshot();c.ChangeCurrent();c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);File.WriteAllBytes(Path.Combine(c.Active,"seed.rollback"),Bytes(65536,2));Require(Fails(()=>c.Store().RecoverRestore()),"Corrupt rollback admitted");c.Original();Require(File.Exists(Path.Combine(c.Active,"disk.rollback")),"First target changed before whole rollback plan validation");});
        test("unknown-current-content-preserved",c=>{var s=c.Snapshot();c.ChangeCurrent();c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);File.WriteAllBytes(c.seed,Bytes(65536,81));string changed=Hash(c.seed);Require(Fails(()=>c.Store().RecoverRestore()),"Unknown target overwritten");Require(Hash(c.seed)==changed&&Hash(c.disk)==c.initialDisk,"Unknown targets were changed");});
        test("pending-restore-fences-another-operation",c=>{var s=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);Require(Fails(()=>c.Snapshot()),"New snapshot ignored pending restore");Require(Fails(()=>c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None)),"Second restore replaced pending journal");Require(Fails(()=>c.Store().AcknowledgeRestore(applied.id)),"Uncommitted restore acknowledged");c.Original();});
        test("separate-instance-exclusive-operation",c=>{bool attempted=false;c.step=p=>{if(p=="create-before-publish"){attempted=true;Require(Fails(()=>c.Store().List()),"Separate instance bypassed OS operation lock");}};c.Snapshot();c.step=null;Require(attempted,"Concurrent operation not attempted");c.Original();});
        test("restore-cancel-after-first-replace",c=>{var s=c.Snapshot();c.ChangeCurrent();var cancel=new CancellationTokenSource();c.step=p=>{if(p=="restore-replaced-disk")cancel.Cancel();};Require(Fails(()=>c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",cancel.Token)),"Restore cancellation ignored");c.step=null;c.Recovered("rolled-back");c.Current();});
        test("strict-journal-inventory",c=>{var s=c.Snapshot();c.ChangeCurrent();c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);var serializer=new JavaScriptSerializer();string file=Path.Combine(c.Active,"journal.json");var raw=serializer.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));raw["extraAuthority"]="untrusted";File.WriteAllText(file,serializer.Serialize(raw));Require(Fails(()=>c.Store().RecoverRestore()),"Unknown journal fields admitted");c.Original();});
        test("stale-transaction-cannot-commit-or-acknowledge-a-later-restore",c=>{var s=c.Snapshot();c.ChangeCurrent();var first=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);c.Store().RecoverRestore();c.Store().AcknowledgeRestore(first.id);var second=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);Require(first.id!=second.id,"Transaction identity reused");Require(Fails(()=>c.Store().CommitRestore(first.id)),"Stale commit accepted for later restore of same snapshot");c.Store().CommitRestore(second.id);Require(Fails(()=>c.Store().AcknowledgeRestore(first.id)),"Stale acknowledgement accepted for later restore");Require(Directory.Exists(c.Active),"Stale acknowledgement archived live transaction");c.Store().AcknowledgeRestore(second.id);c.Original();});
        test("commit-refuses-corrupt-original-rollback",c=>{var s=c.Snapshot();c.ChangeCurrent();var applied=c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);File.WriteAllBytes(Path.Combine(c.Active,"disk.rollback"),Bytes(3*1048576,11));Require(Fails(()=>c.Store().CommitRestore(applied.id)),"Commit reported retained original despite corrupt rollback");Require(new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(c.Active,"journal.json")))["phase"].ToString()=="applied","Failed commit changed journal decision");c.Original();});
        test("strict-journal-types",c=>{var s=c.Snapshot();c.ChangeCurrent();c.Store().PrepareRestore(s.id,"owner-encrypted-current-configuration",CancellationToken.None);var serializer=new JavaScriptSerializer();string file=Path.Combine(c.Active,"journal.json");var raw=serializer.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));raw["version"]="1";File.WriteAllText(file,serializer.Serialize(raw));Require(Fails(()=>c.Store().RecoverRestore()),"String metadata version coerced into authority");c.Original();});
        return new JavaScriptSerializer().Serialize(new {complete=true,checks=results,realFileSystemExercised=true,configurationPersistenceExercised=false,realHyperVExercised=false,protectedAclExercised=false,realDiskFullExercised=false,actualProcessTerminationExercised=false,productSnapshotFeatureEnabled=false});
    }
}
